package store.cadera.cdrjobs.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import store.cadera.cdrjobs.util.JobRanks;import java.util.*;
public final class JobsMenu{public static final String MAIN_TITLE=ChatColor.DARK_AQUA+"CdrJobs • Path of Destiny",MINER_TITLE=ChatColor.DARK_GRAY+"Path • Miner",TRIALS_TITLE=ChatColor.DARK_PURPLE+"Runebound • Trials",FARMER_TITLE=ChatColor.DARK_GREEN+"Path • Farmer",FARMER_TRIALS_TITLE=ChatColor.GREEN+"Verdant • Trials",HUNTER_TITLE=ChatColor.DARK_RED+"Path • Hunter",HUNTER_TRIALS_TITLE=ChatColor.RED+"Bloodfang • Trials",LUMBER_TITLE=ChatColor.GOLD+"Path • Lumberjack",LUMBER_TRIALS_TITLE=ChatColor.DARK_GREEN+"Ironbark • Trials";private final Database db;private final ProfessionStore store;private final LevelService levels;private final MinerTrialService mt;private final FarmerService farmer;private final HunterService hunter;private final LumberjackService lumber;private final NamespacedKey actionKey,skillKey;public JobsMenu(CdrJobsPlugin p,Database d,ProfessionStore s,LevelService l,MinerTrialService m,FarmerService f,HunterService h,LumberjackService w){db=d;store=s;levels=l;mt=m;farmer=f;hunter=h;lumber=w;actionKey=new NamespacedKey(p,"menu_action");skillKey=new NamespacedKey(p,"skill_id");}public NamespacedKey actionKey(){return actionKey;}public NamespacedKey skillKey(){return skillKey;}
public void openMain(Player p){Inventory inv=Bukkit.createInventory(null,27,MAIN_TITLE);inv.setItem(4,item(Material.NETHER_STAR,ChatColor.LIGHT_PURPLE+"✦ Fate Essence: "+db.getFateEssence(p.getUniqueId()),List.of(ChatColor.GRAY+"Global untuk seluruh profession."),null,null));int[]slots={10,12,14,16,22};for(int i=0;i<JobType.values().length;i++){JobType j=JobType.values()[i];JobProgress pr=db.getProgress(p.getUniqueId(),j);if(!j.released()){inv.setItem(slots[i],item(j.icon(),ChatColor.DARK_GRAY+j.displayName(),List.of(ChatColor.GRAY+"Coming soon."),null,null));continue;}String a=switch(j){case MINER->"open_miner";case FARMER->"open_farmer";case HUNTER->"open_hunter";case LUMBERJACK->"open_lumber";default->null;};inv.setItem(slots[i],item(j.icon(),ChatColor.AQUA+"✦ "+j.displayName(),List.of(ChatColor.GRAY+JobRanks.title(j,pr.level()),ChatColor.WHITE+"Level: "+pr.level(),ChatColor.WHITE+"XP: "+(pr.level()>=levels.maxLevel()?"MAX":pr.xp()+"/"+levels.xpRequiredForNextLevel(pr.level())),"",ChatColor.YELLOW+"Klik untuk Path of Ascension."),a,null));}p.openInventory(inv);}
public void openMiner(Player p){Inventory inv=Bukkit.createInventory(null,54,MINER_TITLE);header(inv,p,JobType.MINER,Material.DIAMOND_PICKAXE,ChatColor.AQUA);int[]s={10,19,21,23,28,30,49};MinerSkill[]a={MinerSkill.STONEWHISPER,MinerSkill.RUNEBREAKER,MinerSkill.DEEPBORN,MinerSkill.RUNIC_SURGE,MinerSkill.GEMSEEKER,MinerSkill.ECHO_OF_DEPTH,MinerSkill.HEART_OF_MOUNTAIN};for(int i=0;i<a.length;i++){MinerSkill x=a[i];int r=db.getSkillRank(p.getUniqueId(),x);List<String>l=lore(x.description(),r,x.maxRank(),x.requiredLevel(),x.essenceCost());if(x.prerequisite()!=null)l.add(ChatColor.GRAY+"Requires "+x.prerequisite().displayName()+" "+x.prerequisiteRank());if(x==MinerSkill.RUNIC_SURGE)l.add((mt.isStoneComplete(p)?ChatColor.GREEN:ChatColor.RED)+"Trial of Stone");if(x==MinerSkill.HEART_OF_MOUNTAIN)l.add((mt.isDeepComplete(p)?ChatColor.GREEN:ChatColor.RED)+"Trial of the Deep");inv.setItem(s[i],item(x.icon(),ChatColor.AQUA+"✦ "+x.displayName(),l,"upgrade_miner_skill",x.name()));}inv.setItem(45,item(Material.ECHO_SHARD,ChatColor.LIGHT_PURPLE+"✦ Trials",List.of(ChatColor.YELLOW+"Lihat progress"),"open_miner_trials",null));inv.setItem(53,back("back_main"));p.openInventory(inv);}
public void openTrials(Player p){Inventory inv=Bukkit.createInventory(null,27,TRIALS_TITLE);MinerTrialProgress x=mt.progress(p);inv.setItem(11,item(Material.IRON_PICKAXE,"§b✦ Trial of Stone",List.of("§fOres: "+x.totalOres()+"/"+mt.stoneTarget(),x.stoneComplete()?"§a✓ COMPLETED":"§eRunic Surge gate"),null,null));inv.setItem(15,item(Material.SCULK_CATALYST,"§5✦ Trial of the Deep",List.of("§fDeep: "+x.deepOres()+"/"+mt.deepTarget(),"§fRare: "+x.rareOres()+"/"+mt.rareTarget(),"§fDebris: "+x.ancientDebris()+"/"+mt.ancientTarget(),x.deepComplete()?"§a✓ COMPLETED":"§eAwakening gate"),null,null));inv.setItem(22,back("back_miner"));p.openInventory(inv);}
public void openFarmer(Player p){Inventory inv=Bukkit.createInventory(null,54,FARMER_TITLE);header(inv,p,JobType.FARMER,Material.GOLDEN_HOE,ChatColor.GREEN);int[]s={10,19,21,23,28,30,49};FarmerSkill[]a=FarmerSkill.values();for(int i=0;i<a.length;i++){FarmerSkill x=a[i];int r=store.getSkillRank(p.getUniqueId(),x.key());List<String>l=lore(x.description(),r,x.maxRank(),x.requiredLevel(),x.essenceCost());if(x.prerequisite()!=null)l.add("§7Requires "+x.prerequisite().displayName()+" "+x.prerequisiteRank());if(x==FarmerSkill.VERDANT_BLOOM)l.add((farmer.seedTrialComplete(p)?"§a":"§c")+"Trial of Seed");if(x==FarmerSkill.VERDANT_DOMINION)l.add((farmer.gaiaTrialComplete(p)?"§a":"§c")+"Trial of Gaia");inv.setItem(s[i],item(x.icon(),"§a✦ "+x.displayName(),l,"upgrade_farmer_skill",x.name()));}inv.setItem(45,item(Material.FLOWERING_AZALEA,"§a✦ Trials",List.of("§eLihat progress"),"open_farmer_trials",null));inv.setItem(53,back("back_main"));p.openInventory(inv);}
public void openFarmerTrials(Player p){Inventory inv=Bukkit.createInventory(null,27,FARMER_TRIALS_TITLE);inv.setItem(11,item(Material.WHEAT,"§a✦ Trial of Seed",List.of("§fHarvests: "+farmer.harvests(p)+"/"+farmer.seedTarget(),farmer.seedTrialComplete(p)?"§a✓ COMPLETED":"§eVerdant Bloom gate"),null,null));inv.setItem(15,item(Material.ENCHANTED_GOLDEN_APPLE,"§2✦ Trial of Gaia",List.of("§fHarvests: "+farmer.harvests(p)+"/"+farmer.gaiaHarvestTarget(),"§fRare: "+farmer.rareHarvests(p)+"/"+farmer.gaiaRareTarget(),farmer.gaiaTrialComplete(p)?"§a✓ COMPLETED":"§eAwakening gate"),null,null));inv.setItem(22,back("back_farmer"));p.openInventory(inv);}
public void openHunter(Player p){Inventory inv=Bukkit.createInventory(null,54,HUNTER_TITLE);header(inv,p,JobType.HUNTER,Material.IRON_SWORD,ChatColor.RED);int[]s={10,19,21,23,28,30,49};HunterSkill[]a=HunterSkill.values();for(int i=0;i<a.length;i++){HunterSkill x=a[i];int r=store.getSkillRank(p.getUniqueId(),x.key());List<String>l=lore(x.description(),r,x.maxRank(),x.requiredLevel(),x.essenceCost());if(x.prerequisite()!=null)l.add("§7Requires "+x.prerequisite().displayName()+" "+x.prerequisiteRank());if(x==HunterSkill.CRIMSON_HUNT)l.add((hunter.fangComplete(p)?"§a":"§c")+"Trial of Fang");if(x==HunterSkill.APEX_PREDATOR)l.add((hunter.moonComplete(p)?"§a":"§c")+"Trial of Crimson Moon");inv.setItem(s[i],item(x.icon(),"§c✦ "+x.displayName(),l,"upgrade_hunter_skill",x.name()));}inv.setItem(45,item(Material.WITHER_SKELETON_SKULL,"§c✦ Trials",List.of("§eLihat progress"),"open_hunter_trials",null));inv.setItem(53,back("back_main"));p.openInventory(inv);}
public void openHunterTrials(Player p){Inventory inv=Bukkit.createInventory(null,27,HUNTER_TRIALS_TITLE);inv.setItem(11,item(Material.BONE,"§c✦ Trial of Fang",List.of("§fKills: "+hunter.kills(p)+"/"+hunter.fangTarget(),hunter.fangComplete(p)?"§a✓ COMPLETED":"§eCrimson Hunt gate"),null,null));inv.setItem(15,item(Material.ECHO_SHARD,"§4✦ Crimson Moon",List.of("§fKills: "+hunter.kills(p)+"/"+hunter.moonKillTarget(),"§fNight: "+hunter.nightKills(p)+"/"+hunter.moonNightTarget(),"§fDangerous: "+hunter.dangerousKills(p)+"/"+hunter.moonDangerTarget(),hunter.moonComplete(p)?"§a✓ COMPLETED":"§eAwakening gate"),null,null));inv.setItem(22,back("back_hunter"));p.openInventory(inv);}
public void openLumber(Player p){Inventory inv=Bukkit.createInventory(null,54,LUMBER_TITLE);header(inv,p,JobType.LUMBERJACK,Material.IRON_AXE,ChatColor.GOLD);int[]s={10,19,21,23,28,30,49};LumberjackSkill[]a=LumberjackSkill.values();for(int i=0;i<a.length;i++){LumberjackSkill x=a[i];int r=store.getSkillRank(p.getUniqueId(),x.key());List<String>l=lore(x.description(),r,x.maxRank(),x.requiredLevel(),x.essenceCost());if(x.prerequisite()!=null)l.add("§7Requires "+x.prerequisite().displayName()+" "+x.prerequisiteRank());if(x==LumberjackSkill.GROVE_RHYTHM)l.add((lumber.timberComplete(p)?"§a":"§c")+"Trial of Timber");if(x==LumberjackSkill.OATH_YGGDRASIL)l.add((lumber.groveComplete(p)?"§a":"§c")+"Trial of Ancient Grove");inv.setItem(s[i],item(x.icon(),"§6✦ "+x.displayName(),l,"upgrade_lumber_skill",x.name()));}inv.setItem(45,item(Material.OAK_SAPLING,"§6✦ Trials",List.of("§eLihat progress"),"open_lumber_trials",null));inv.setItem(53,back("back_main"));p.openInventory(inv);}
public void openLumberTrials(Player p){Inventory inv=Bukkit.createInventory(null,27,LUMBER_TRIALS_TITLE);inv.setItem(11,item(Material.OAK_LOG,"§6✦ Trial of Timber",List.of("§fNatural logs: "+lumber.logs(p)+"/"+lumber.timberTarget(),lumber.timberComplete(p)?"§a✓ COMPLETED":"§eGrove Rhythm gate"),null,null));inv.setItem(15,item(Material.TOTEM_OF_UNDYING,"§2✦ Trial of Ancient Grove",List.of("§fLogs: "+lumber.logs(p)+"/"+lumber.groveLogTarget(),"§fElder logs: "+lumber.elderLogs(p)+"/"+lumber.groveElderTarget(),lumber.groveComplete(p)?"§a✓ COMPLETED":"§eAwakening gate"),null,null));inv.setItem(22,back("back_lumber"));p.openInventory(inv);}
private void header(Inventory i,Player p,JobType j,Material m,ChatColor c){JobProgress pr=db.getProgress(p.getUniqueId(),j);i.setItem(4,item(m,c+j.displayName(),List.of("§7"+JobRanks.title(j,pr.level()),"§fLevel: §b"+pr.level(),"§dFate Essence: "+db.getFateEssence(p.getUniqueId())),null,null));}private List<String>lore(String d,int r,int max,int lv,int cost){List<String>l=new ArrayList<>();l.add("§7"+d);l.add("");l.add("§fRank: §b"+r+"/"+max);l.add("§fRequires Lv."+lv);l.add("§dCost: "+cost+" Fate Essence");l.add("");l.add(r>=max?"§aMAXIMUM RANK":"§eKlik untuk upgrade.");return l;}private ItemStack back(String a){return item(Material.ARROW,"§eKembali",List.of(),a,null);}private ItemStack item(Material m,String n,List<String>l,String a,String sk){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();meta.setDisplayName(n);meta.setLore(l);meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);if(a!=null)meta.getPersistentDataContainer().set(actionKey,PersistentDataType.STRING,a);if(sk!=null)meta.getPersistentDataContainer().set(skillKey,PersistentDataType.STRING,sk);i.setItemMeta(meta);return i;}}
